p=Path('src/documents/OpeningUsageAssessment.tsx');p.write_text('''import {docInput} from "./CatalogPicker";
import {normalizeViNumber} from "../../shared/documentNumbers";
import {openingUsageAssessment} from "../../shared/openingUsageAssessment";
import type {DraftLine} from "../../shared/documents";
import {money} from "./documentFormatting";

type Props={item:DraftLine;index:number;disabled:boolean;line:(id:string,patch:Partial<DraftLine>)=>void};
export function OpeningUsageAssessment({item,index,disabled,line}:Props){
 let amount:number|null=null,error="";
 try{amount=openingUsageAssessment({...item,quantity:normalizeViNumber(item.quantity,"Số lượng"),opening_current_unit_price:normalizeViNumber(item.opening_current_unit_price??"","Nguyên giá"),opening_quality_percent:normalizeViNumber(item.opening_quality_percent??"","Tỷ lệ còn lại")}).amount_vnd;}catch(e){error=e instanceof Error?e.message:"Số liệu không hợp lệ.";}
 return <>
  <td className="p-2 align-top"><input className={docInput} aria-label={"Nguyên giá đầu kỳ dòng "+(index+1)} inputMode="decimal" placeholder="Theo giá mua DMVT" value={item.opening_current_unit_price??""} disabled={disabled} onChange={e=>line(item.id,{opening_current_unit_price:e.target.value})}/></td>
  <td className="p-2 align-top"><input className={docInput} aria-label={"Tỷ lệ còn lại đầu kỳ (%) dòng "+(index+1)} inputMode="decimal" placeholder="0–100%" value={item.opening_quality_percent??""} disabled={disabled} onChange={e=>line(item.id,{opening_quality_percent:e.target.value})}/></td>
  <td className="p-2 align-top tabular-nums" aria-label={"Giá trị còn lại đầu kỳ dòng "+(index+1)}><div className="flex min-h-[34px] items-center font-semibold">{money(amount)}</div>{error?<p role="status" className="mt-1 text-xs text-amber-700">{error}</p>:amount===null&&<p className="mt-1 text-xs text-slate-500">Chờ đủ nguyên giá, tỷ lệ và xác nhận.</p>}</td>
  <td className="space-y-2 p-2 align-top"><input className={docInput} aria-label={"Người xác nhận đầu kỳ dòng "+(index+1)} placeholder="Kỹ thuật / người xác nhận" maxLength={256} value={item.opening_assessor??""} disabled={disabled} onChange={e=>line(item.id,{opening_assessor:e.target.value})}/><textarea className={docInput+" resize-y"} aria-label={"Căn cứ xác nhận đầu kỳ dòng "+(index+1)} placeholder="Biên bản, căn cứ xác nhận…" maxLength={1000} rows={2} value={item.opening_confirmation_basis??""} disabled={disabled} onChange={e=>line(item.id,{opening_confirmation_basis:e.target.value})}/></td>
 </>;
}
''',encoding='utf-8')
